CREATE TABLE IF NOT EXISTS organizations(id TEXT PRIMARY KEY,name TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS profiles(id TEXT PRIMARY KEY,org_id TEXT NOT NULL REFERENCES organizations(id),email TEXT UNIQUE NOT NULL,name TEXT NOT NULL,role TEXT NOT NULL CHECK(role IN ('driver','operator','engineer','admin')),password_hash TEXT NOT NULL,notifications INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS sessions(token_hash TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES profiles(id),expires_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS invitations(id TEXT PRIMARY KEY,org_id TEXT NOT NULL REFERENCES organizations(id),email TEXT NOT NULL,role TEXT NOT NULL,token_hash TEXT UNIQUE NOT NULL,expires_at TEXT NOT NULL,used INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS vehicles(id TEXT PRIMARY KEY,org_id TEXT NOT NULL REFERENCES organizations(id),name TEXT NOT NULL,model TEXT NOT NULL DEFAULT 'BEMAC 68VM Passenger',image_url TEXT NOT NULL DEFAULT '/bemac-white.png',nominal_voltage REAL NOT NULL DEFAULT 55.2,nominal_capacity REAL NOT NULL DEFAULT 80);
CREATE TABLE IF NOT EXISTS assignments(vehicle_id TEXT PRIMARY KEY REFERENCES vehicles(id),driver_id TEXT NOT NULL REFERENCES profiles(id));
CREATE TABLE IF NOT EXISTS devices(id TEXT PRIMARY KEY,vehicle_id TEXT NOT NULL UNIQUE REFERENCES vehicles(id),token_hash TEXT NOT NULL,firmware_version TEXT,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS telemetry(id TEXT PRIMARY KEY,device_id TEXT NOT NULL REFERENCES devices(id),mode TEXT NOT NULL CHECK(mode IN ('hardware','demo')),boot_id TEXT NOT NULL,sequence INTEGER NOT NULL,received_at TEXT NOT NULL,measured_at TEXT NOT NULL,payload TEXT NOT NULL,UNIQUE(device_id,mode,boot_id,sequence));
CREATE INDEX IF NOT EXISTS telemetry_device_time ON telemetry(device_id,mode,received_at);
CREATE TABLE IF NOT EXISTS energy_measurements(id TEXT PRIMARY KEY,telemetry_id TEXT NOT NULL REFERENCES telemetry(id),device_id TEXT NOT NULL REFERENCES devices(id),mode TEXT NOT NULL,source TEXT NOT NULL,power_w REAL,increment_wh REAL NOT NULL,measured_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS gps_records(id TEXT PRIMARY KEY,telemetry_id TEXT NOT NULL REFERENCES telemetry(id),device_id TEXT NOT NULL REFERENCES devices(id),mode TEXT NOT NULL,latitude REAL NOT NULL,longitude REAL NOT NULL,measured_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS gps_device_time ON gps_records(device_id,mode,measured_at);
CREATE TABLE IF NOT EXISTS security_events(id TEXT PRIMARY KEY,device_id TEXT NOT NULL REFERENCES devices(id),mode TEXT NOT NULL,type TEXT NOT NULL,created_at TEXT NOT NULL,ack_by TEXT REFERENCES profiles(id),UNIQUE(device_id,mode,id));
CREATE TABLE IF NOT EXISTS help_requests(id TEXT PRIMARY KEY,org_id TEXT NOT NULL REFERENCES organizations(id),vehicle_id TEXT NOT NULL REFERENCES vehicles(id),driver_id TEXT NOT NULL REFERENCES profiles(id),mode TEXT NOT NULL,type TEXT NOT NULL,notes TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN ('pending','acknowledged','resolved')),created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS messages(id TEXT PRIMARY KEY,org_id TEXT NOT NULL REFERENCES organizations(id),vehicle_id TEXT NOT NULL REFERENCES vehicles(id),sender_id TEXT NOT NULL REFERENCES profiles(id),mode TEXT NOT NULL,body TEXT NOT NULL,created_at TEXT NOT NULL,read_at TEXT);
CREATE TABLE IF NOT EXISTS bench_sessions(id TEXT PRIMARY KEY,device_id TEXT NOT NULL REFERENCES devices(id),engineer_id TEXT NOT NULL REFERENCES profiles(id),mode TEXT NOT NULL,created_at TEXT NOT NULL,closed_at TEXT);
CREATE TABLE IF NOT EXISTS bench_results(id TEXT PRIMARY KEY,session_id TEXT NOT NULL REFERENCES bench_sessions(id),test TEXT NOT NULL,result TEXT NOT NULL CHECK(result IN ('PASS','FAIL','BLOCKED','NOT TESTED')),measurements TEXT NOT NULL,notes TEXT NOT NULL,evidence TEXT NOT NULL,firmware TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS calibrations(id TEXT PRIMARY KEY,device_id TEXT NOT NULL REFERENCES devices(id),engineer_id TEXT NOT NULL REFERENCES profiles(id),sensor TEXT NOT NULL,values_json TEXT NOT NULL,evidence TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS audit_logs(id TEXT PRIMARY KEY,org_id TEXT NOT NULL REFERENCES organizations(id),user_id TEXT REFERENCES profiles(id),action TEXT NOT NULL,target TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS vehicle_images(vehicle_id TEXT PRIMARY KEY REFERENCES vehicles(id),mime TEXT NOT NULL,base64 TEXT NOT NULL,uploaded_by TEXT NOT NULL REFERENCES profiles(id),uploaded_at TEXT NOT NULL);
